 * - Falls back to createdAt when plannedDate is null/undefined
 */

import { describe, it, expect } from 'vitest'
import { getDateAnchor } from '../dateAnchor.js'

describe('getDateAnchor', () => {
  const createdAt = 1706745600000 // 2024-02-01T00:00:00Z in epoch ms

  it('returns plannedDate when present', () => {
    const plannedDate = 1706832000000 // 2024-02-02T00:00:00Z
    expect(getDateAnchor({ plannedDate, createdAt })).toBe(plannedDate)
  })

  it('falls back to createdAt when plannedDate is null', () => {
    expect(getDateAnchor({ plannedDate: null, createdAt })).toBe(createdAt)
  })

  it('falls back to createdAt when plannedDate is undefined', () => {
    // @ts-expect-error — testing runtime behavior with missing field
    expect(getDateAnchor({ createdAt })).toBe(createdAt)
  })

  it('returns the same epoch ms value (no Date object conversion)', () => {
    const plannedDate = 1706832000000
    const result = getDateAnchor({ plannedDate, createdAt })
    expect(typeof result).toBe('number')
    expect(result).toBe(plannedDate)
  })
})

